function calc_deversity()
                    local k = #session_tag_list;
                    local sim = 0;
                    for i=1, #session_tag_list-1 do
                        for j=i+1, #session_tag_list do
                            if session_tag_list[i] == session_tag_list[j] then
                                sim = sim + 1;
                            end
                        end
                    end
                    local ils = 2/(k*(k-1)) * sim
                    local ils_diversity = 1 - ils;
                    return math.floor(ils_diversity * 10000), ils_diversity * 10000.0;
                end

